  const [loading, setLoading] = useState("");

  if (!isVisible) return null;

  const addTokenFaucetToWallet = async (id, ticker, address, abi) => {
    setLoading(id);

    await getFaucet(ticker, address, abi);

    setLoading(null);
  };

  const tokens = [
    {
      id: 1,
      title: "ArbiFake",
      ticker: "AFAKE",
      address: NEW_ARBIFAKE_ADDRESS,
      abi: ArbiFake.abi,
